.sl-contact-split { background-color: var(--smartlearn-bg); color: var(--smartlearn-text); font-family: var(--smartlearn-body-font, system-ui, sans-serif); padding-block: clamp(3rem, 6vw, 4.5rem); padding-inline: clamp(1rem, 3vw, 2rem); }
.sl-contact-split .sl-container { max-width: 1200px; width: 100%; margin-inline: auto; }
.sl-contact-split .sl-split-grid { display: grid; grid-template-columns: 1fr 1.25fr; gap: clamp(2rem, 5vw, 3.5rem); align-items: center; }
.sl-contact-split .sl-eyebrow { display: inline-block; padding: 0.4rem 0.9rem; border-radius: 999px; font-size: 0.85rem; font-weight: 600; background-color: rgba(148, 163, 184, 0.12); background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent); color: var(--smartlearn-primary); margin-bottom: 1rem; }
.sl-contact-split .sl-title { font-family: var(--smartlearn-heading-font, inherit); font-weight: 800; font-size: clamp(2rem, 4vw, 2.75rem); color: var(--smartlearn-text); margin: 0 0 1rem; line-height: 1.15; }
.sl-contact-split .sl-subtitle { color: var(--smartlearn-text-muted); font-size: 1.075rem; line-height: 1.6; margin: 0 0 2rem; }
.sl-contact-split .sl-info-list { display: flex; flex-direction: column; gap: 1.25rem; margin-bottom: 2rem; }
.sl-contact-split .sl-info-item { display: flex; align-items: flex-start; gap: 1rem; }
.sl-contact-split .contact-icon { width: 48px; height: 48px; border-radius: 50%; flex-shrink: 0; display: flex; align-items: center; justify-content: center; background-color: rgba(148, 163, 184, 0.12); background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent); color: var(--smartlearn-primary); }
.sl-contact-split .sl-info-title { font-family: var(--smartlearn-heading-font, inherit); font-size: 1.05rem; font-weight: 700; color: var(--smartlearn-text); margin: 0 0 0.25rem; }
.sl-contact-split .sl-info-desc { color: var(--smartlearn-text-muted); margin: 0; line-height: 1.5; }
.sl-contact-split .sl-info-link { color: var(--smartlearn-text-muted); text-decoration: none; }
.sl-contact-split .sl-info-link:hover { color: var(--smartlearn-primary); text-decoration: underline; }
.sl-contact-split .social-links { display: flex; gap: 0.625rem; flex-wrap: wrap; }
.sl-contact-split .sl-social-btn { width: 44px; height: 44px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.35)); color: var(--smartlearn-text); text-decoration: none; transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease; }
.sl-contact-split .sl-social-btn:hover { background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); border-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); }
.sl-contact-split .contact-form-wrapper { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); border-radius: var(--smartlearn-radius, 1rem); padding: clamp(1.5rem, 4vw, 2.75rem); box-shadow: 0 20px 45px rgba(0, 0, 0, 0.08); }
.sl-contact-split .sl-form-title { font-family: var(--smartlearn-heading-font, inherit); font-size: 1.4rem; font-weight: 700; color: var(--smartlearn-text); margin: 0 0 1.5rem; }
.sl-contact-split .sl-fields-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
.sl-contact-split .sl-field-full { grid-column: 1 / -1; }
.sl-contact-split .sl-label { display: block; font-size: 0.875rem; font-weight: 600; color: var(--smartlearn-text-muted); margin-bottom: 0.35rem; }
.sl-contact-split .sl-input { width: 100%; min-height: 46px; padding: 0.65rem 1rem; border-radius: var(--smartlearn-radius, 0.5rem); background-color: var(--smartlearn-input-bg, var(--smartlearn-bg)); border: 1px solid var(--smartlearn-input-border, var(--smartlearn-card-border, rgba(148, 163, 184, 0.35))); color: var(--smartlearn-text); font-size: 1rem; }
.sl-contact-split .sl-input:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 1px; border-color: var(--smartlearn-primary); }
.sl-contact-split .sl-submit-btn { width: 100%; min-height: 48px; padding: 0.85rem 1.5rem; border-radius: var(--smartlearn-radius, 0.5rem); border: none; background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); font-weight: 700; font-size: 1rem; cursor: pointer; }
.sl-contact-split .sl-submit-btn:hover { background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); }
.sl-contact-split .sl-submit-btn:focus-visible, .sl-contact-split a:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-contact-split .sl-form-status { margin-top: 0.875rem; font-size: 0.925rem; font-weight: 600; color: var(--smartlearn-primary); min-height: 1.25em; }
.sl-contact-split .sl-form-status.is-error { color: #dc2626; }
@media (max-width: 991px) { .sl-contact-split .sl-split-grid { grid-template-columns: 1fr; } }
@media (max-width: 575px) { .sl-contact-split .sl-fields-grid { grid-template-columns: 1fr; } }
@media (prefers-reduced-motion: reduce) { .sl-contact-split .sl-social-btn { transition: none; } }

