(function() {
  var init = function() {
    document.querySelectorAll('.sl-contact-split').forEach(function(root, idx) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var uid = 'sl-csplit-' + idx + '-' + Math.random().toString(36).slice(2, 7);
      var form = root.querySelector('.sl-form');
      if (!form) return;
      form.querySelectorAll('[data-sl-field]').forEach(function(input) {
        var key = input.getAttribute('data-sl-field');
        var fieldId = uid + '-' + key;
        input.id = fieldId;
        var label = form.querySelector('[data-sl-for="' + key + '"]');
        if (label) label.setAttribute('for', fieldId);
      });
      var status = form.querySelector('.sl-form-status');
      form.addEventListener('submit', function(e) {
        e.preventDefault();
        var fn = form.querySelector('[name="first_name"]');
        var ln = form.querySelector('[name="last_name"]');
        var emailEl = form.querySelector('[name="email"]');
        var msgEl = form.querySelector('[name="message"]');
        [fn, ln, emailEl, msgEl].forEach(function(el) { if (el) el.removeAttribute('aria-invalid'); });
        if (fn && !fn.value.trim()) {
          fn.setAttribute('aria-invalid', 'true'); fn.focus();
          if (status) { status.textContent = 'Please enter your first name.'; status.classList.add('is-error'); }
          return;
        }
        if (ln && !ln.value.trim()) {
          ln.setAttribute('aria-invalid', 'true'); ln.focus();
          if (status) { status.textContent = 'Please enter your last name.'; status.classList.add('is-error'); }
          return;
        }
        if (emailEl && (!emailEl.value.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailEl.value.trim()))) {
          emailEl.setAttribute('aria-invalid', 'true'); emailEl.focus();
          if (status) { status.textContent = 'Please enter a valid email address.'; status.classList.add('is-error'); }
          return;
        }
        if (msgEl && !msgEl.value.trim()) {
          msgEl.setAttribute('aria-invalid', 'true'); msgEl.focus();
          if (status) { status.textContent = 'Please enter your message.'; status.classList.add('is-error'); }
          return;
        }
        if (status) { status.textContent = 'Thank you! We will get back to you within 24 hours.'; status.classList.remove('is-error'); }
        form.reset();
      });
    });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
